type ApiOk<T> = T extends void ? { ok: true } : { ok: true; data: T }

type Unwrap<T> = T extends Promise<infer R> ? Unwrap<R> : T

type ToArray<T> = T extends unknown ? T[] : never
type NoDistribute<T> = [T] extends [unknown] ? T[] : never

async function mutate<T>(path: string, body: unknown): Promise<ApiOk<T>> {
  const data = await api.post(path, body)
  // parse at the boundary; the conditional type is the caller's contract
  return (data === undefined ? { ok: true } : { ok: true, data }) as ApiOk<T>
}

type A = ToArray<string | number> // string[] | number[]
type B = NoDistribute<string | number> // (string | number)[]

